,p_plug_name=>'Home'
,p_static_id=>'home'
,p_title=>'&{HOME}.'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4504868307683981366
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_available  number;',
'    v_active     number;',
'    v_customers  number;',
'    v_revenue    number;',
'    v_manager    boolean := apex_authorization.is_authorized(''Manager Rights'');',
'    v_logo       varchar2(500) := apex_plugin_util.replace_substitutions(''#APP_FILES#rentflow-logo.svg'');',
'begin',
'    select count(*) into v_available from CARS where status = ''AVAILABLE'';',
'    select count(*) into v_active    from BOOKINGS where status = ''ACTIVE'';',
'    select count(*) into v_customers from CUSTOMERS;',
'',
'    htp.p(q''~<style>',
'      .wd-hero{background:linear-gradient(135deg,#14213D,#1d3557);color:#fff;text-align:center;padding:40px 16px 90px;border-radius:16px}',
'      .wd-hero img{width:88px;height:88px}',
'      .wd-hero h1{color:#fff;margin:12px 0 4px;font-size:2.4rem}',
'      .wd-hero p{opacity:.8;margin:0}',
'      .wd-kpis{display:flex;flex-wrap:wrap;gap:16px;justify-content:center;margin:-60px 16px 0}',
'      .wd-kpi{background:#fff;color:#14213D;border-radius:14px;padding:18px 24px;min-width:200px;box-shadow:0 4px 14px rgba(0,0,0,.12);text-align:center}',
'      .wd-kpi b{display:block;font-size:1.8rem}',
'      .wd-actions{display:flex;flex-wrap:wrap;gap:12px;justify-content:center;margin:28px 0}',
'      .wd-actions a{background:#fff;border:1px solid #ddd;border-radius:10px;padding:10px 18px;text-decoration:none;color:#14213D;font-weight:600}',
'      .wd-actions a.main{background:#F28C28;border-color:#F28C28;color:#fff}',
'      .wd-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}',
'      .wd-card{background:#fff;border-radius:14px;border-top:5px solid #F28C28;padding:20px;text-decoration:none;color:#14213D;box-shadow:0 2px 10px rgba(0,0,0,.08)}',
'      .wd-card h3{margin:0 0 6px}',
'      .wd-card span{color:#666;font-size:.9rem}',
'      .wd-activity{background:#fff;color:#14213D;border-radius:14px;padding:16px 20px;margin-top:24px;box-shadow:0 2px 10px rgba(0,0,0,.08)}',
'      .wd-activity li{padding:8px 0;border-bottom:1px solid #eee;list-style:none}',
'      </style>~'');',
'',
'    -- hero',
'    htp.p(''<div class="wd-hero"><img src="'' || v_logo || ''" alt="Masar"><h1>Masar</h1><p>Smart car rental management system</p></div>'');',
'',
'    -- KPI tiles (revenue for managers only)',
'    htp.p(''<div class="wd-kpis">'');',
'    htp.p(''<div class="wd-kpi"><b>'' || v_available || ''</b>Available cars</div>'');',
'    htp.p(''<div class="wd-kpi"><b>'' || v_active || ''</b>Active bookings</div>'');',
'    htp.p(''<div class="wd-kpi"><b>'' || v_customers || ''</b>Customers</div>'');',
'    htp.p(''</div>'');',
'',
'    -- quick actions',
'    htp.p(''<div class="wd-actions">'');',
'    htp.p(''<a class="main" href="'' || apex_page.get_url(p_page => 8 , p_clear_cache => ''8'') || ''">+ New Booking</a>'');',
'    htp.p(''<a href="'' || apex_page.get_url(p_page => 3 , p_clear_cache => ''3'') || ''">Add Car</a>'');',
'    htp.p(''<a href="'' || apex_page.get_url(p_page => 5 , p_clear_cache => ''5'') || ''">Add Customer</a>'');',
'    htp.p(''<a href="'' || apex_page.get_url(p_page => 9 , p_clear_cache => ''9'') || ''">Return Car</a>'');',
'    htp.p(''</div>'');',
'',
'    -- section cards',
'    htp.p(''<div class="wd-cards">'');',
'    htp.p(''<a class="wd-card" href="'' || apex_page.get_url(p_page => 2) || ''"><h3>Cars</h3><span>Browse and manage the fleet</span></a>'');',
'    htp.p(''<a class="wd-card" href="'' || apex_page.get_url(p_page => 4) || ''"><h3>Customers</h3><span>Customer records and licenses</span></a>'');',
'    htp.p(''<a class="wd-card" href="'' || apex_page.get_url(p_page => 6) || ''"><h3>Bookings</h3><span>Rentals, returns and payments</span></a>'');',
'    if v_manager then',
'        htp.p(''<a class="wd-card" href="'' || apex_page.get_url(p_page => 10) || ''"><h3>Dashboard</h3><span>Revenue and fleet analytics</span></a>'');',
'    end if;',
'    htp.p(''</div>'');',
'',
'    -- recent activity',
'    htp.p(''<div class="wd-activity"><h3>Recent bookings</h3><ul style="margin:0;padding:0">'');',
'    for r in (select booking_id , customer_name , plate_number , status',
'              from BOOKING_DETAILS',
'              order by booking_id desc',
'              fetch first 3 rows only) loop',
'        htp.p(''<li>Booking #'' || r.booking_id || '' - '' || apex_escape.html(r.customer_name) || '' - '' || apex_escape.html(r.plate_number) || '' ('' || r.status || '')</li>'');',
'    end loop;',
'    htp.p(''</ul></div>'');',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_created_on=>wwv_flow_imp.dz('20261029041102Z')
,p_updated_on=>wwv_flow_imp.dz('20261029044107Z')
,p_created_by=>'LAMAR22068@GMAIL.COM'
,p_updated_by=>'LAMAR22068@GMAIL.COM'
);
end;
