 p_id=>wwv_flow_imp.id(7553862472342703733)
,p_plug_name=>'KPIs'
,p_static_id=>'kpis'
,p_title=>'&{KPIS}.'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4504868307683981366
,p_plug_display_sequence=>1
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    v_revenue   number;',
'    v_month_rev number;',
'    v_total     number;',
'    v_rented    number;',
'    v_maint     number;',
'    v_active    number;',
'    v_due_today number;',
'    v_occ       number;',
'    v_maint_pct number;',
'begin',
'    select nvl(sum(amount) , 0) into v_revenue from PAYMENTS;',
'    select nvl(sum(amount) , 0) into v_month_rev from PAYMENTS where trunc(payment_datetime , ''MM'') = trunc(sysdate , ''MM'');',
'    select count(*) , count(case when status = ''RENTED'' then 1 end) , count(case when status = ''MAINTENANCE'' then 1 end)',
'    into v_total , v_rented , v_maint from CARS;',
'    select count(*) , count(case when trunc(end_datetime) = trunc(sysdate) then 1 end)',
'    into v_active , v_due_today from BOOKINGS where status = ''ACTIVE'';',
'',
'    v_occ       := case when v_total = 0 then 0 else round(v_rented / v_total * 100) end;',
'    v_maint_pct := case when v_total = 0 then 0 else round(v_maint / v_total * 100 , 1) end;',
'',
'    htp.p(q''~<style>',
'.dk{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-bottom:16px}',
'.dk-c{background:#fff;color:#14213D;border-radius:14px;padding:18px 20px;box-shadow:0 2px 10px rgba(0,0,0,.08);border-top:5px solid #F28C28}',
'.dk-c small{color:#666}',
'.dk-c b{display:block;font-size:2rem;margin:6px 0}',
'.dk-bar{height:8px;background:#e5e7eb;border-radius:4px;overflow:hidden}',
'.dk-bar i{display:block;height:100%;background:#3b82f6}',
'</style>~'');',
'',
'    htp.p(''<div class="dk">'');',
'    htp.p(''<div class="dk-c" style="border-top-color:#10b981"><small>Total Revenue (SAR)</small><b>'' || to_char(v_revenue , ''FM999,999,990'') || ''</b><small>This month: '' || to_char(v_month_rev , ''FM999,999,990'') || ''</small></div>'');',
'    htp.p(''<div class="dk-c" style="border-top-color:#3b82f6"><small>Fleet Occupancy</small><b>'' || v_occ || ''%</b><div class="dk-bar"><i style="width:'' || v_occ || ''%"></i></div><small>'' || v_rented || '' / '' || v_total || '' cars rented</small></div>'
||''');',
'    htp.p(''<div class="dk-c"><small>Active Bookings</small><b>'' || v_active || ''</b><small>'' || v_due_today || '' due today</small></div>'');',
'    htp.p(''<div class="dk-c" style="border-top-color:#ef4444"><small>Cars in Maintenance</small><b>'' || v_maint || ''</b><small>'' || v_maint_pct || ''% of the fleet</small></div>'');',
'    htp.p(''</div>'');',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_created_on=>wwv_flow_imp.dz('20261029042415Z')
,p_updated_on=>wwv_flow_imp.dz('20261029044107Z')
,p_created_by=>'LAMAR22068@GMAIL.COM'
,p_updated_by=>'LAMAR22068@GMAIL.COM'
);
